import React, { useState } from 'react';
import {
  EmotionAnalysis,
  RiskAssessment,
  EmotionStyle,
  ProblemAnalysis,
  InterventionInfo,
  EMOTION_NAMES,
  PROBLEM_CATEGORY_NAMES,
  RISK_LEVEL_NAMES
} from '../types';

interface ReportPanelProps {
  emotion: EmotionAnalysis;
  risk: RiskAssessment;
  problem?: ProblemAnalysis;
  intervention?: InterventionInfo;
  analysisSources?: { emotion: string; risk: string; problem: string };
  llmUsed?: boolean;
  emotionStyle: EmotionStyle;
  report: string;
}

export const ReportPanel: React.FC<ReportPanelProps> = ({
  emotion,
  risk,
  problem,
  intervention,
  analysisSources,
  llmUsed,
  emotionStyle,
  report
}) => {
  const [isExpanded, setIsExpanded] = useState(false);

  const riskColors: Record<string, string> = {
    low: '#4CAF50',
    medium: '#FF9800',
    high: '#F44336',
    critical: '#9C27B0'
  };

  const lowConfidence = emotion.confidence < 0.45;
  const toggleLabel = isExpanded ? '\u25BC' : '\u25B6';

  const handleExport = () => {
    const blob = new Blob([report], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `心理咨询报告_${new Date().toLocaleDateString('zh-CN').replace(/\//g, '-')}.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="report-panel">
      <div
        className="report-header"
        onClick={() => setIsExpanded(!isExpanded)}
        onKeyDown={(e) => e.key === 'Enter' && setIsExpanded(!isExpanded)}
        role="button"
        tabIndex={0}
      >
        <div className="report-title">
          <span className="report-icon">{'\uD83D\uDCCB'}</span>
          <span>心理咨询报告</span>
        </div>
        <div className="report-toggle">{toggleLabel}</div>
      </div>

      {isExpanded && (
        <div className="report-content">
          {lowConfidence && (
            <div className="report-disclaimer">
              情绪识别置信度较低，以下分析仅供参考，如有持续困扰建议寻求专业心理评估。
            </div>
          )}

          {(analysisSources || llmUsed !== undefined) && (
            <div className="report-section">
              <div className="section-title">分析来源</div>
              <p className="analysis-source-line">
                情绪：{analysisSources?.emotion || 'rule'}
                {' · '}
                风险：{analysisSources?.risk || 'rule'}
                {' · '}
                问题：{analysisSources?.problem || 'rule'}
                {llmUsed ? '（已启用 LLM 辅助）' : '（仅规则引擎）'}
              </p>
            </div>
          )}

          {intervention && (
            <div className="report-section">
              <div className="section-title">干预框架</div>
              <div className="framework-badge">{intervention.frameworkName}</div>
            </div>
          )}

          {problem && (
            <div className="report-section">
              <div className="section-title">问题分类</div>
              <div className="problem-card">
                <span className="problem-main">
                  {PROBLEM_CATEGORY_NAMES[problem.category] || problem.category}
                </span>
                <span className="confidence">置信度: {(problem.confidence * 100).toFixed(0)}%</span>
                {problem.subcategories.length > 0 && (
                  <div className="problem-subs">
                    可能涉及：{problem.subcategories.slice(0, 4).join('、')}
                  </div>
                )}
              </div>
            </div>
          )}

          <div className="report-section">
            <div className="section-title">情绪分析</div>
            <div className="emotion-card" style={{ borderColor: emotionStyle.color }}>
              <div className="emotion-header">
                <span className="emotion-badge" style={{ backgroundColor: emotionStyle.color }}>
                  {EMOTION_NAMES[emotion.emotion] || emotion.emotion}
                </span>
                <span className="confidence">置信度: {(emotion.confidence * 100).toFixed(0)}%</span>
              </div>
              {emotion.keywords.length > 0 && (
                <div className="emotion-keywords">
                  <span className="keywords-label">关键词:</span>
                  {emotion.keywords.map((kw, i) => (
                    <span key={i} className="keyword-tag">
                      {kw}
                    </span>
                  ))}
                </div>
              )}
            </div>
          </div>

          <div className="report-section">
            <div className="section-title">风险评估</div>
            <div className="risk-card" style={{ borderColor: riskColors[risk.level] }}>
              <div className="risk-header">
                <span className="risk-badge" style={{ backgroundColor: riskColors[risk.level] }}>
                  风险等级: {RISK_LEVEL_NAMES[risk.level]}
                </span>
              </div>
              {risk.keywords.length > 0 && (
                <div className="risk-keywords">
                  <span className="keywords-label">预警关键词:</span>
                  {risk.keywords.map((kw, i) => (
                    <span key={i} className="keyword-tag warning">
                      {kw}
                    </span>
                  ))}
                </div>
              )}
              {risk.warningMessage && (
                <div className="warning-message" style={{ borderColor: riskColors[risk.level] }}>
                  {risk.warningMessage}
                </div>
              )}
              <div className="hotline">{risk.hotline}</div>
            </div>
          </div>

          <div className="report-section">
            <div className="section-title">完整报告</div>
            <div className="full-report">
              <pre>{report}</pre>
            </div>
          </div>

          <div className="report-actions">
            <button type="button" className="action-btn export-btn" onClick={handleExport}>
              导出报告
            </button>
          </div>
        </div>
      )}
    </div>
  );
};
